query:
ALTER TABLE transfer_requests 
ADD COLUMN IF NOT EXISTS pricing_mode TEXT DEFAULT 'zone_tariff' CHECK (pricing_mode IN ('provider_quote', 'zone_tariff'));

-- Also add provider_cost_with_vat to transfer_items for storing the provider cost + 10% VAT per item
ALTER TABLE transfer_items 
ADD COLUMN IF NOT EXISTS provider_cost NUMERIC DEFAULT NULL;

